"""
API中转站 - 聚合多个免费模型，统一OpenAI兼容接口
启动: python server.py
端口: 8888
"""

import json, time, hashlib, secrets, os, logging
from flask import Flask, request, jsonify, Response
import requests

app = Flask(__name__)
logging.basicConfig(level=logging.INFO, format='[%(asctime)s] %(message)s')

# ========== 加载配置 ==========
CONFIG_PATH = os.path.join(os.path.dirname(__file__), "config.json")
with open(CONFIG_PATH, "r", encoding="utf-8") as f:
    config = json.load(f)

ACCESS_TOKEN = config["access_token"]
UPSTREAM_KEYS = config["upstream_keys"]
MODEL_ROUTES = config["model_routes"]

# Key轮询计数器（多Key负载均衡）
key_index = {}

def get_upstream_key(provider):
    """轮询获取上游Key"""
    keys = UPSTREAM_KEYS.get(provider, [])
    if not keys:
        return None
    idx = key_index.get(provider, 0)
    key_index[provider] = (idx + 1) % len(keys)
    return keys[idx]

def resolve_upstream(model_name):
    """根据模型名找到对应的上游配置"""
    for prefix, route in MODEL_ROUTES.items():
        if model_name.startswith(prefix):
            key = get_upstream_key(route["provider"])
            if not key:
                return {"error": f"上游 {route['provider']} 未配置Key，请在 config.json 填写"}
            return {
                "base_url": route["base_url"],
                "api_key": key,
                "provider": route["provider"],
            }
    return {"error": f"未找到模型 {model_name} 的路由配置"}

# ========== 认证中间件 ==========
def check_auth():
    auth = request.headers.get("Authorization", "")
    token = auth.replace("Bearer ", "")
    if token != ACCESS_TOKEN:
        return False
    return True

@app.before_request
def auth_middleware():
    if request.path == "/health":
        return None
    if not check_auth():
        return jsonify({"error": "无效的访问Token"}), 401
    return None

# ========== API端点 ==========

@app.route("/health", methods=["GET"])
def health():
    """健康检查（无需认证）"""
    providers_status = {}
    for provider, keys in UPSTREAM_KEYS.items():
        providers_status[provider] = f"{len(keys)}个Key已配置"
    return jsonify({
        "status": "ok",
        "providers": providers_status,
        "models": list(MODEL_ROUTES.keys()),
    })

@app.route("/v1/models", methods=["GET"])
def list_models():
    """列出可用模型"""
    models = [{"id": prefix, "object": "model"} for prefix in MODEL_ROUTES]
    return jsonify({"object": "list", "data": models})

@app.route("/v1/chat/completions", methods=["POST"])
def chat_completions():
    """OpenAI兼容的聊天接口"""
    data = request.get_json()
    if not data:
        return jsonify({"error": "请求体为空"}), 400

    model = data.get("model", "")
    messages = data.get("messages", [])
    stream = data.get("stream", False)
    max_tokens = data.get("max_tokens", 2048)
    temperature = data.get("temperature", 0.7)

    # 解析上游
    upstream = resolve_upstream(model)
    if "error" in upstream:
        return jsonify({"error": upstream["error"]}), 400

    logging.info(f"→ {model} → {upstream['provider']} (stream={stream})")

    # 构造上游请求
    upstream_url = f"{upstream['base_url']}/chat/completions"
    headers = {
        "Authorization": f"Bearer {upstream['api_key']}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": model.replace(f"{upstream['provider']}-", "", 1),  # 去掉前缀
        "messages": messages,
        "max_tokens": max_tokens,
        "temperature": temperature,
        "stream": stream,
    }

    if stream:
        # 流式转发
        def generate():
            try:
                resp = requests.post(upstream_url, headers=headers, json=payload, stream=True, timeout=120)
                for chunk in resp.iter_content(chunk_size=None):
                    if chunk:
                        yield chunk
            except Exception as e:
                yield f'data: {{"error": "{str(e)}"}}\n\n'.encode()
        return Response(generate(), mimetype="text/event-stream")

    else:
        # 普通请求
        try:
            resp = requests.post(upstream_url, headers=headers, json=payload, timeout=120)
            return jsonify(resp.json()), resp.status_code
        except Exception as e:
            return jsonify({"error": f"上游调用失败: {str(e)}"}), 502

# ========== 管理接口 ==========

@app.route("/admin/keys", methods=["GET"])
def list_keys():
    """查看当前Key配置（隐藏密钥）"""
    masked = {}
    for provider, keys in UPSTREAM_KEYS.items():
        masked[provider] = [k[:8] + "***" if k else "(空)" for k in keys]
    return jsonify(masked)

@app.route("/admin/reload", methods=["POST"])
def reload_config():
    """热重载配置"""
    global config, UPSTREAM_KEYS, MODEL_ROUTES
    with open(CONFIG_PATH, "r", encoding="utf-8") as f:
        config = json.load(f)
    UPSTREAM_KEYS = config["upstream_keys"]
    MODEL_ROUTES = config["model_routes"]
    return jsonify({"status": "配置已重载"})

# ========== 启动 ==========

if __name__ == "__main__":
    print(f"""
╔══════════════════════════════════════╗
║     🚀 API中转站已启动              ║
║     地址: http://127.0.0.1:8888     ║
║     密钥: {ACCESS_TOKEN[:12]}...    ║
║     健康检查: /health               ║
║     可用模型: {len(MODEL_ROUTES)}个 ║
╚══════════════════════════════════════╝
""")
    app.run(host="0.0.0.0", port=8888, debug=False)
